using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class LocalInspectionFindingsTests
{
    static ContractWorld New(string? policy=LocalInspectionFindings.Policy)=>NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],"person:shingen",20261022,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,null,policy);
    static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
    static EntityId Own(WorldSession s,string id="request:inspect-findings"){Assert.Equal(ResultCode.Accepted,s.Submit(NewGameWorld.Inspect(s.DiagnosticSnapshot(),id),s.Revision).Code);return s.DiagnosticSnapshot().Tasks.Last().Id;}
    static BranchEdge[] Local(ContractWorld w)=>BranchRoutes.GraphEdges(w).Where(e=>(e.From=="kofu"||e.To=="kofu")&&!NationalRoutes.Sea(e.Id)).OrderBy(e=>e.Id).ToArray();
    static ContractWorld Conditions(params RoadCondition[] changes){var w=New();w.Couriers=w.Couriers! with{Conditions=changes};return w;}
    static EntityId Work(WorldSession s,bool accept=true){Assert.Equal(ResultCode.Accepted,s.Submit(NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:local-findings"),s.Revision).Code);At(s,1);var t=s.DiagnosticSnapshot().Tasks.Last();var message=s.GetActorView(s.PlayerControl).Messages.Single(m=>m.KnownBody==null);Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,message.Id,s.Revision).Code);Assert.Equal(ResultCode.Accepted,s.Assent(t.Id,s.PlayerControl,accept,s.Revision).Code);return t.Id;}
    [Fact]public void OldWorldDoesNotReceiveFindings(){var s=new WorldSession(New(null));var id=Own(s);At(s,8);Assert.Empty(LocalInspectionFindings.View(s,s.PlayerControl,id));Assert.DoesNotContain(s.DiagnosticSnapshot().Evidence,e=>e.Id.Value.Contains("/inspected-road/"));}
    [Fact]public void ObservationsOnlyAppearOnActualCompletion(){var s=new WorldSession(New());var id=Own(s);At(s,1);Assert.Empty(LocalInspectionFindings.View(s,s.PlayerControl,id));At(s,4);Assert.Empty(LocalInspectionFindings.View(s,s.PlayerControl,id));At(s,5);Assert.NotEmpty(LocalInspectionFindings.View(s,s.PlayerControl,id));}
    [Fact]public void OnlyLocalLandRoadsAreObserved(){var initial=New();var s=new WorldSession(initial);var id=Own(s);At(s,8);var rows=LocalInspectionFindings.View(s,s.PlayerControl,id);Assert.Equal(Local(initial).Select(e=>e.Id),rows.Select(r=>r.Edge));Assert.All(rows,r=>{Assert.Equal(new EntityId("site:kofu"),r.Site);Assert.Equal(Local(initial).Single(e=>e.Id==r.Edge).LengthMm,r.LengthMm);Assert.Equal(5,r.ObservedAt);Assert.True(r.Direct);});}
    [Fact]public void HiddenRemoteConditionCannotChangeVisibleFindings(){var initial=New();string remote=BranchRoutes.GraphEdges(initial).First(e=>e.From!="kofu"&&e.To!="kofu").Id;var a=new WorldSession(initial);var b=new WorldSession(Conditions(new RoadCondition(2,remote,true)));var ta=Own(a);var tb=Own(b);At(a,8);At(b,8);Assert.Equal(ContractJson.Write(LocalInspectionFindings.View(a,a.PlayerControl,ta)),ContractJson.Write(LocalInspectionFindings.View(b,b.PlayerControl,tb)));Assert.DoesNotContain(remote,b.GetBranchView(b.PlayerControl).KnownBlockedEdges);}
    [Fact]public void LocalBlockIsLearnedAtInspectionNotBefore(){string edge=Local(New())[0].Id;var s=new WorldSession(Conditions(new RoadCondition(2,edge,true)));var id=Own(s);At(s,4);Assert.DoesNotContain(edge,s.GetBranchView(s.PlayerControl).KnownBlockedEdges);At(s,5);Assert.Contains(edge,s.GetBranchView(s.PlayerControl).KnownBlockedEdges);Assert.True(LocalInspectionFindings.View(s,s.PlayerControl,id).Single(r=>r.Edge==edge).Blocked);}
    [Fact]public void LaterTruthCannotRewriteEarlierObservation(){string edge=Local(New())[0].Id;var s=new WorldSession(Conditions(new RoadCondition(2,edge,true),new RoadCondition(8,edge,false)));var id=Own(s);At(s,6);var before=ContractJson.Write(LocalInspectionFindings.View(s,s.PlayerControl,id));At(s,10);Assert.Equal(before,ContractJson.Write(LocalInspectionFindings.View(s,s.PlayerControl,id)));Assert.Contains(edge,s.GetBranchView(s.PlayerControl).KnownBlockedEdges);}
    [Fact]public void NewInspectionCanUpdateKnowledgeWithoutDeletingOldRecord(){string edge=Local(New())[0].Id;var s=new WorldSession(Conditions(new RoadCondition(2,edge,true),new RoadCondition(8,edge,false)));var first=Own(s);At(s,10);var second=Own(s,"request:inspect-again");At(s,18);Assert.True(LocalInspectionFindings.View(s,s.PlayerControl,first).Single(r=>r.Edge==edge).Blocked);Assert.False(LocalInspectionFindings.View(s,s.PlayerControl,second).Single(r=>r.Edge==edge).Blocked);Assert.DoesNotContain(edge,s.GetBranchView(s.PlayerControl).KnownBlockedEdges);}
    [Fact]public void RecipientNeedsPhysicalArrivalAndOpening(){var s=new WorldSession(New());var id=Work(s);At(s,5);var t=s.DiagnosticSnapshot().Tasks.Single(t=>t.Id==id);Assert.Empty(LocalInspectionFindings.View(s,t.Issuer,id));At(s,6);Assert.Empty(LocalInspectionFindings.View(s,t.Issuer,id));var notes=s.DiagnosticSnapshot().Outbox.Where(o=>o.Task==id&&o.Kind=="route-observation").ToArray();Assert.NotEmpty(notes);foreach(var note in notes)Assert.Equal(ResultCode.Accepted,s.Open(t.Issuer,note.Id,s.Revision).Code);Assert.Equal(Local(New()).Length,LocalInspectionFindings.View(s,t.Issuer,id).Length);Assert.All(LocalInspectionFindings.View(s,t.Issuer,id),r=>{Assert.False(r.Direct);Assert.Equal(5,r.ObservedAt);Assert.Equal(6,r.LearnedAt);});}
    [Fact]public void DuplicateOpeningDoesNotDuplicateKnowledgeOrExecution(){var s=new WorldSession(New());var id=Work(s);At(s,6);var note=s.DiagnosticSnapshot().Outbox.First(o=>o.Task==id&&o.Kind=="route-observation");Assert.Equal(ResultCode.Accepted,s.Open(note.Recipient,note.Id,s.Revision).Code);Assert.Equal(ResultCode.AlreadyAccepted,s.Open(note.Recipient,note.Id,s.Revision).Code);Assert.Single(LocalInspectionFindings.View(s,note.Recipient,id));Assert.Single(s.DiagnosticSnapshot().EffectLedger,e=>e.Task==id&&e.BusinessKey==id.Value+"/finish/1");}
    [Fact]public void EditedObservationIsRejected(){var s=new WorldSession(New());Own(s);At(s,8);var w=s.DiagnosticSnapshot();var e=w.Evidence.First(e=>e.Id.Value.Contains("/inspected-road/"));w.Evidence=w.Evidence.Select(x=>x.Id==e.Id?x with{Claim=e.Claim.Replace("route-open:","route-block:")}:x).ToArray();Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void MissingReportPaperIsRejected(){var s=new WorldSession(New());var id=Work(s);At(s,8);var w=s.DiagnosticSnapshot();w.Outbox=w.Outbox.Where(o=>o.Kind!="route-observation").ToArray();Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void UnexpectedObservationOutboxCannotBypassTerminalCount(){var s=new WorldSession(New());Own(s);At(s,8);var w=s.DiagnosticSnapshot();var report=w.Outbox.Single();w.Outbox=[..w.Outbox,report with{Id=new("message:unexpected-note"),Kind="route-observation",Sent=false}];Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void DeclinedTaskCannotCreateFindings(){var s=new WorldSession(New());var id=Work(s,false);At(s,10);Assert.Empty(LocalInspectionFindings.View(s,s.PlayerControl,id));Assert.DoesNotContain(s.DiagnosticSnapshot().Outbox,o=>o.Task==id&&o.Kind=="route-observation");}
    [Fact]public void UnknownPolicyIsRejected(){Assert.Throws<InvalidDataException>(()=>New("unknown"));}
    [Fact]public void ProfilePinsPolicyAndOldProfileRemainsExact(){var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"inspection-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],"person:shingen",20261022,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,null,LocalInspectionFindings.Policy);Assert.Equal(LocalInspectionFindings.Policy,store.Read(p.Instance).InspectionPolicy);Assert.Throws<InvalidDataException>(()=>NewCampaignStore.Build(p with{InspectionPolicy=null}));var old=ContractJson.Read<NewCampaignProfile>(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","pre-routine-household-v3.json")));Assert.Null(old.InspectionPolicy);Assert.Equal(old.InitialHash,ContractJson.CanonicalHash(NewCampaignStore.Build(old)));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(4)][InlineData(5)][InlineData(6)][InlineData(8)]public void SaveRestoresObservationsAndSameFuture(int at){var s=new WorldSession(New());Own(s);At(s,at);s.SetPaused(true);var initial=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"inspection-save-"+Guid.NewGuid().ToString("N")),initial.Definitions);store.Save(s,"manual",initial.WorldId,new(0,1));var host=new WorldSessionHost(new(New()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.CanonicalHash(initial),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));At(s,20);At(host.Current,20);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));}
}
